// HIGHLANDER v7 (runner-safe).
// Only the NEWEST inbound message in a burst reaches the agent, so a rapid run of
// texts gets ONE considered answer instead of three overlapping ones.
//
// HISTORY - read before changing this node:
//  v5 compared message TEXT, so two identical messages ("Hello" twice) both matched
//     the newest message and both replied.
//  v6 compared the WhatsApp send timestamp against Chatwoot's created_at. Those are
//     two DIFFERENT clocks: created_at is stamped when WE log the message, which is
//     after the debounce Wait. So every message looked older than itself, every run
//     returned [] and the bot went completely silent while still reporting success.
//  v7 compares Chatwoot message IDs, which are the same scale on both sides.
//
// Referenced nodes are limited to Check Latest Msg + Capture Conv ID, both of which
// always execute on this path, including the media path (reading a NON-executed node
// blocks forever under the external task runner - that was the old hang).

const messages = ($('Check Latest Msg').first().json.payload) || [];

let myId = null;
try { myId = Number($('Capture Conv ID').first().json.id); } catch (e) {}

const incoming = messages.filter(m => m && m.message_type === 0 && m.id != null);
const ids = incoming.map(m => Number(m.id));

// FAIL OPEN in every ambiguous case. A duplicate reply is recoverable, silence is not.
if (!myId || !ids.length) return $input.all();
if (!ids.includes(myId)) return $input.all();

// Only the newest inbound message answers for the whole burst.
if (myId === Math.max.apply(null, ids)) return $input.all();
return [];

// Identity gate. Everything WhatsApp sends us lands here first, and most of it is
// not a customer. This node's only job is to decide who is talking and whether we
// should be listening at all.
const employees = [
  "9715XXXXXX09", "9715XXXXXX05", "9715XXXXXX03", "9715XXXXXX08", 
  "9715XXXXXX10", "9715XXXXXX02", "9715XXXXXX07", "9715XXXXXX06", "9715XXXXXX01"
];
const admins = [""];
// Our own numbers. Meta echoes our outbound messages back through the same webhook,
// so without this list the bot answers itself in a loop until the API rate-limits us.
// This happened once. It cost a day.
const myBusinessNumber = "9715XXXXXX04"; 

// Pull the fields we need without assuming the payload shape. Meta changes it.
const webhookData = $('whatsapp-api').first().json;
const value = webhookData.body?.entry?.[0]?.changes?.[0]?.value;

// Empty payloads arrive during delivery-receipt storms. Drop them silently.
if (!value || !value.messages || value.messages.length === 0) return [];

const message = value.messages[0];
const sender = message.from;
const msgType = message.type;

// Profile name comes free in the payload, so the agent never opens with "what is your name".
const contactName = value.contacts?.[0]?.profile?.name || "";

// Reactions. A thumbs-up on our own reply is not a new enquiry.
if (msgType === 'reaction') return [];

// The loop stopper. If the sender is us, stop here.

if (sender === myBusinessNumber) return [];

// Status callbacks (sent, delivered, read) come through the same webhook as messages.

// Anything reaching this line should be a real inbound message. Check anyway.
if (value.statuses) return []; 

// Normalise the message body into one shape the rest of the flow can rely on.
let content = "";
if (msgType === "text") {
    content = message.text.body;
} else if (msgType === "image") {
    content = `📷 [Image Sent] ID: ${message.image.id}`;
    if (message.image.caption) content += `\nCaption: ${message.image.caption}`;
} else if (msgType === "audio") {
    content = `🎤 [Voice Note Sent] ID: ${message.audio.id}`;
} else if (msgType === "document") {
    content = `📄 [Document Sent] ${message.document.filename || "File"}`;
} else {
    content = `[${msgType} message]`;
}

// Cheap first-pass classification. Staff numbers are known, so they skip the LLM
// entirely and go down the internal-ops branch instead of the customer branch.
let userType = "customer";
if (admins.includes(sender) && content.startsWith("/")) {
  userType = "command";
} else if (employees.includes(sender)) {
  userType = "employee";
}

return {
  json: {
    user_type: userType,
    phone: sender,
    contact_name: contactName,
    user_query: content,
    message_type: msgType,
    raw_message: message
  }
};

const input = $input.item.json;
let source_id = null;
let contact_id = null;

// Contact already in Chatwoot. Reuse the id rather than creating a duplicate,
// otherwise conversation history fragments and the agent loses the thread.
if (input.payload && Array.isArray(input.payload) && input.payload.length > 0) {
    const contact = input.payload[0];
    contact_id = contact.id;
    if (contact.contact_inboxes && contact.contact_inboxes.length > 0) {
        source_id = contact.contact_inboxes[0].source_id;
    }
}

// First time we have seen this number. Take the id the create call just returned.
else if (input.payload && input.payload.contact) {
    const contact = input.payload.contact;
    contact_id = contact.id;
    if (contact.source_id) {
        source_id = contact.source_id;
    } else if (contact.contact_inboxes && contact.contact_inboxes.length > 0) {
         source_id = contact.contact_inboxes[0].source_id;
    }
}

if (!source_id && input.source_id) source_id = input.source_id;
if (!contact_id && input.id) contact_id = input.id;

return { json: { source_id: source_id, contact_id: contact_id } };

const msg =  $('whatsapp-api').first().json.body.entry[0].changes[0].value.messages[0];
const text = msg.text?.body || msg.image?.caption || "";
const isDone = text.toUpperCase().trim().startsWith("DONE");
let jobCode = "";
if (isDone) {
  jobCode = text.substring(4).trim().toUpperCase(); 
}
return { 
  json: { 
    text: text, 
    is_done_command: isDone, 
    job_code: jobCode,
    sender: msg.from
  } 
};

// REPEAT OFFENDER GATE (narrowed deliberately)
// Previously ANY vendor/job_seeker/spam label muted the conversation forever.
// One misclassification therefore killed a real lead in silence: a customer who
// pasted our own earlier replies back at us was read as a "vendor" pitch, the
// label stuck, and every later message from her was dropped with the execution
// still reporting success.
// Only hard spam mutes now. Vendors and job seekers are re-classified cheaply on
// each message and still get their canned reply from the Traffic Router, so they
// never reach the expensive agent, but a wrong label can no longer bury a sale.
const labels = $input.first().json.payload || [];
const blockedLabels = ['spam'];
const isBlocked = labels.some(label => blockedLabels.includes(label));

if (isBlocked) {
    return []; // Silent stop - message is already logged in Chatwoot
}

return $input.all();

let uq='';
try{ const h=$('Call Media Helper').first(); if(h && h.json && (h.json.user_query||'').trim()) uq=h.json.user_query; }catch(e){}
if(!uq){ try{ uq=$('Universal Normalizer').first().json.user_query||''; }catch(e){} }
return [{ json:{ user_query: uq } }];

// Split the agent reply into at most two WhatsApp bubbles.
// Also scrubs the marker itself so a malformed marker can never reach the
// customer or the Chatwoot log (we saw a literal "[SPLIT]" delivered).
let out = (($json.output) || '') + '';

// normalise spacing/case variants the model emits: [ SPLIT ], [split], etc.
out = out.replace(/\[\s*SPLIT\s*\]/gi, '[SPLIT]');

let parts = out.split('[SPLIT]').map(s => s.trim()).filter(Boolean);
if (parts.length === 0) parts = [out.trim()];
if (parts.length > 2) parts = [parts[0], parts.slice(1).join('\n\n')];

// final scrub: any surviving bracketed marker, or a bare SPLIT on its own line
parts = parts
  .map(p => p.replace(/\[\s*SPLIT\s*\]/gi, ' ')
             .replace(/^[ \t]*SPLIT[ \t]*$/gim, '')
             .replace(/\n{3,}/g, '\n\n')
             .replace(/[ \t]{2,}/g, ' ')
             .trim())
  .filter(Boolean);

if (parts.length === 0) parts = [out.trim()];
return parts.map(p => ({ json: { output: p } }));

// Deterministic parse of the Gatekeeper LLM output (no fragile structured parser).
// Handles fenced or raw JSON, single or double nesting. Defaults to CUSTOMER on any
// failure so a genuine lead is never dropped.
let t = $json.text;
if (t == null) t = $json.response != null ? $json.response : ($json.output != null ? $json.output : '');

let parsed = null;
if (t && typeof t === 'object') {
  parsed = t;
} else {
  let s = String(t || '').trim();
  const m = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (m) s = m[1].trim();
  if (!s.startsWith('{')) { const i = s.indexOf('{'); const j = s.lastIndexOf('}'); if (i !== -1 && j !== -1) s = s.slice(i, j + 1); }
  try { parsed = JSON.parse(s); } catch (e) { parsed = null; }
}

const core = parsed && parsed.output ? parsed.output : (parsed || {});
const allowed = ['CUSTOMER', 'VENDOR', 'JOB_SEEKER', 'SPAM'];
let category = (core.category || '').toString().toUpperCase().trim();
if (!allowed.includes(category)) category = 'CUSTOMER';

return [{ json: { output: { category: category, reason: (core.reason || '').toString() } } }];
